import ppidSchema from "@tepian-k3/schema/platform/ppid.schema";
import {
  createTRPCRouter,
  formDataInput,
  formDataProcedure,
  withPermission,
  withRateLimit,
} from "../..";
import ppidQueries from "@tepian-k3/queries/platform/ppid.queries";
import auditQueries from "@tepian-k3/queries/platform/audit.queries";
import z from "zod";
import { TRPCError } from "@trpc/server";
import { runEffect } from "../../utils/run-effect";
import { rateLimiters } from "@tepian-k3/services/rate-limiter";
import { Effect } from "effect";
import { processAndUploadFile } from "../../utils/image-upload";

export const ppidRouter = createTRPCRouter({
  // ==================== PUBLIC ENDPOINTS ====================

  /**
   * Get public PPID documents with pagination & search
   */
  getPublicDocuments: withRateLimit(rateLimiters.moderate())
    .input(ppidSchema.getPPIDDocumentsSchema)
    .query(async ({ input }) => {
      const { data, pageCount } = await runEffect(
        ppidQueries.getOffsetPaginatedPPIDDocuments({
          ...input,
          isActive: true, // Public can only see active documents
        }),
      );
      return { data, pageCount };
    }),

  /**
   * Get public PPID document detail by ID
   */
  getPublicDocumentById: withRateLimit(rateLimiters.moderate())
    .input(z.object({ id: z.uuidv7() }))
    .query(async ({ input }) => {
      const doc = await runEffect(ppidQueries.getPPIDDocumentById(input.id));
      if (!doc || !doc.isActive) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Dokumen PPID tidak ditemukan atau tidak aktif",
        });
      }
      return doc;
    }),

  /**
   * Track submission status by Ticket Number and Email
   */
  trackSubmission: withRateLimit(rateLimiters.strict())
    .input(ppidSchema.trackPPIDSubmissionSchema)
    .query(async ({ input }) => {
      const submission = await runEffect(
        ppidQueries.getPPIDSubmissionByTicket(input.ticketNumber, input.email),
      );
      if (!submission) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Tiket permohonan tidak ditemukan dengan email tersebut",
        });
      }
      return submission;
    }),

  /**
   * Submit PPID information request (Public)
   */
  submitRequest: withRateLimit(rateLimiters.strict())
    .input(formDataInput)
    .use(formDataProcedure(ppidSchema.createPPIDSubmissionSchema))
    .mutation(async ({ ctx }) =>
      runEffect(
        Effect.gen(function* () {
          // Upload all identity/supporting files to S3/MinIO
          const uploadedFiles = yield* Effect.forEach(
            ctx.input.data.identityFiles,
            (file) =>
              Effect.map(
                processAndUploadFile(file, {
                  folder: "ppid-identity",
                  maxSize: 5 * 1024 * 1024, // 5MB limit per file
                  allowedMimeTypes: [
                    "application/pdf",
                    "image/jpeg",
                    "image/png",
                    "image/webp",
                  ],
                }),
                (uploaded) => ({
                  key: uploaded.key,
                  name: file.name,
                  size: file.size,
                }),
              ),
            { concurrency: 2 },
          );

          // Save to database
          const result = yield* ppidQueries.createPPIDSubmission(
            ctx.input.data,
            uploadedFiles,
            ctx.user?.id, // Link to account if authenticated
          );

          return result;
        }),
      ),
    ),

  // ==================== ADMIN ENDPOINTS ====================

  /**
   * Get all PPID documents (Admin)
   */
  getAdminDocuments: withPermission("ppid-documents.read")
    .input(ppidSchema.getPPIDDocumentsSchema)
    .query(async ({ input }) => {
      const { data, pageCount } = await runEffect(
        ppidQueries.getOffsetPaginatedPPIDDocuments(input),
      );
      return { data, pageCount };
    }),

  /**
   * Get PPID Document by ID (Admin)
   */
  getAdminDocumentById: withPermission("ppid-documents.read")
    .input(z.object({ id: z.uuidv7() }))
    .query(async ({ input }) => {
      const doc = await runEffect(ppidQueries.getPPIDDocumentById(input.id));
      if (!doc) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Dokumen PPID tidak ditemukan",
        });
      }
      return doc;
    }),

  /**
   * Create PPID Document (Admin)
   */
  createDocument: withPermission("ppid-documents.create")
    .input(formDataInput)
    .use(formDataProcedure(ppidSchema.createPPIDDocumentSchema))
    .mutation(async ({ ctx }) =>
      runEffect(
        Effect.gen(function* () {
          let fileData = null;
          if (ctx.input.data.file) {
            const uploaded = yield* processAndUploadFile(ctx.input.data.file, {
              folder: "ppid-documents",
            });
            fileData = {
              key: uploaded.key,
              name: ctx.input.data.file.name,
              size: ctx.input.data.file.size,
            };
          }

          const result = yield* ppidQueries.createPPIDDocument(
            ctx.input.data,
            fileData,
          );

          // Log Audit
          yield* auditQueries.createAuditLog({
            entityType: "ppid_documents",
            entityId: result.id,
            action: "create",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: null,
            newValues: result,
            description: `Membuat dokumen PPID baru: ${result.title}`,
          });

          return result;
        }),
      ),
    ),

  /**
   * Update PPID Document (Admin)
   */
  updateDocument: withPermission("ppid-documents.update")
    .input(formDataInput)
    .use(formDataProcedure(ppidSchema.updatePPIDDocumentSchema))
    .mutation(async ({ ctx }) =>
      runEffect(
        Effect.gen(function* () {
          const oldDoc = yield* ppidQueries.getPPIDDocumentById(
            ctx.input.data.id,
          );
          if (!oldDoc) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Dokumen PPID tidak ditemukan",
            });
          }

          let fileData = null;
          if (ctx.input.data.file) {
            const uploaded = yield* processAndUploadFile(ctx.input.data.file, {
              folder: "ppid-documents",
            });
            fileData = {
              key: uploaded.key,
              name: ctx.input.data.file.name,
              size: ctx.input.data.file.size,
            };
          }

          const result = yield* ppidQueries.updatePPIDDocument(
            ctx.input.data.id,
            ctx.input.data,
            fileData,
          );

          // Log Audit
          yield* auditQueries.createAuditLog({
            entityType: "ppid_documents",
            entityId: result.id,
            action: "update",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldDoc,
            newValues: result,
            description: `Memperbarui dokumen PPID: ${result.title}`,
          });

          return result;
        }),
      ),
    ),

  /**
   * Delete PPID Document (Admin)
   */
  deleteDocument: withPermission("ppid-documents.delete")
    .input(z.object({ id: z.uuidv7() }))
    .mutation(async ({ ctx, input }) =>
      runEffect(
        Effect.gen(function* () {
          const oldDoc = yield* ppidQueries.getPPIDDocumentById(input.id);
          if (!oldDoc) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Dokumen PPID tidak ditemukan",
            });
          }

          const result = yield* ppidQueries.deletePPIDDocument(input.id);

          // Log Audit
          yield* auditQueries.createAuditLog({
            entityType: "ppid_documents",
            entityId: input.id,
            action: "delete",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldDoc,
            newValues: null,
            description: `Menghapus dokumen PPID: ${oldDoc.title}`,
          });

          return result;
        }),
      ),
    ),

  /**
   * Get all PPID requests/submissions (Admin)
   */
  getAdminSubmissions: withPermission("ppid-submissions.read")
    .input(ppidSchema.getPPIDSubmissionsSchema)
    .query(async ({ input }) => {
      const { data, pageCount } = await runEffect(
        ppidQueries.getOffsetPaginatedPPIDSubmissions(input),
      );
      return { data, pageCount };
    }),

  /**
   * Get PPID Submission by ID (Admin)
   */
  getAdminSubmissionById: withPermission("ppid-submissions.read")
    .input(z.object({ id: z.uuidv7() }))
    .query(async ({ input }) => {
      const submission = await runEffect(
        ppidQueries.getPPIDSubmissionById(input.id),
      );
      if (!submission) {
        throw new TRPCError({
          code: "NOT_FOUND",
          message: "Data permohonan tidak ditemukan",
        });
      }
      return submission;
    }),

  /**
   * Process and update submission status (Admin Approve/Reject/Complete)
   */
  updateSubmissionStatus: withPermission("ppid-submissions.update")
    .input(formDataInput)
    .use(formDataProcedure(ppidSchema.updatePPIDSubmissionStatusSchema))
    .mutation(async ({ ctx }) =>
      runEffect(
        Effect.gen(function* () {
          const oldSub = yield* ppidQueries.getPPIDSubmissionById(
            ctx.input.data.id,
          );
          if (!oldSub) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Data permohonan tidak ditemukan",
            });
          }

          let responseFile = null;
          if (ctx.input.data.responseFile) {
            const uploaded = yield* processAndUploadFile(
              ctx.input.data.responseFile,
              {
                folder: "ppid-responses",
              },
            );
            responseFile = {
              key: uploaded.key,
              name: ctx.input.data.responseFile.name,
              size: ctx.input.data.responseFile.size,
            };
          }

          const result = yield* ppidQueries.updatePPIDSubmissionStatus(
            ctx.input.data.id,
            ctx.input.data.status,
            ctx.input.data.adminNotes,
            responseFile,
          );

          // Log Audit
          yield* auditQueries.createAuditLog({
            entityType: "ppid_submissions",
            entityId: result.id,
            action: "update",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldSub,
            newValues: result,
            description: `Mengubah status permohonan PPID (${result.ticketNumber}) menjadi ${result.status.toUpperCase()}`,
          });

          return result;
        }),
      ),
    ),

  /**
   * Delete PPID Submission (Admin)
   */
  deleteSubmission: withPermission("ppid-submissions.delete")
    .input(z.object({ id: z.uuidv7() }))
    .mutation(async ({ ctx, input }) =>
      runEffect(
        Effect.gen(function* () {
          const oldSub = yield* ppidQueries.getPPIDSubmissionById(input.id);
          if (!oldSub) {
            throw new TRPCError({
              code: "NOT_FOUND",
              message: "Permohonan PPID tidak ditemukan",
            });
          }

          const result = yield* ppidQueries.deletePPIDSubmission(input.id);

          // Log Audit
          yield* auditQueries.createAuditLog({
            entityType: "ppid_submissions",
            entityId: input.id,
            action: "delete",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldSub,
            newValues: null,
            description: `Menghapus permohonan PPID (${oldSub.ticketNumber})`,
          });

          return result;
        }),
      ),
    ),
});

